    10	const OPACITY_ICON_HOVER = 0.6;
    11	const OPACITY_ICON_DISABLED = 0.4;
    12	// 0.15s, matching baseStyle. Deliberately NOT var(--zimm-motion-duration-fast) (200ms):
    13	// see baseStyle's transition comment above — that decision was to leave 0.15s as-is pending
    14	// the UI designer rather than retime silently, and motion.ts is itself marked provisional.
    15	// Retiming only the icon variants would leave this file running two different durations.
    16	// One constant so icon/iconInverse cannot drift.
    17	const ICON_TRANSITION = 'opacity 0.15s ease';
    18	
    19	// fontFamily/fontWeight/lineHeight/letterSpacing/textTransform come from sizes.lg/sm's
    20	// textStyle (below), not here — button always renders with a size (defaultProps.size
    21	// is 'lg', there's no sizeless render path), so a duplicate fallback here would only
    22	// ever mask the per-size textStyle value instead of letting it apply.
    23	const baseStyle = {
    24	  borderRadius: 0,
    25	  // 0.15s matches no motion token (fast 200ms / default 300ms) — left as-is
    26	  // pending the UI designer's confirmation rather than retimed silently.
    27	  transition: 'background-color 0.15s ease, border-color 0.15s ease, color 0.15s ease',
    28	  // Focus ring per Handover button.md §focus: outline only, no background change.
    29	  // Replaces the previous outline:none + bg-swap, which gave the primary variant an
