     1	import React from 'react';
     2	import { chakra, useStyleConfig } from '@chakra-ui/react';
     3	import { isBlankRichText, parseRichText } from 'app/utils/richText';
     4	
     5	const ZIMM_PRODUCT_DESCRIPTION_RECIPE = 'ZimmProductDescription';
     6	
     7	type ZimmProductDescriptionProps = {
     8	  /**
     9	   * The product's long description, as authored in Business Manager. Parsed into React nodes
    10	   * rather than injected as HTML — see `app/utils/richText` for why.
    11	   */
    12	  description?: string;
    13	};
    14	
    15	/**
    16	 * Atom — the product description. Renders nothing when the product has no description, so a
    17	 * caller can place it unconditionally.
    18	 */
    19	export const ZimmProductDescription = ({ description }: ZimmProductDescriptionProps) => {
    20	  const styles = useStyleConfig(ZIMM_PRODUCT_DESCRIPTION_RECIPE, {});
    21	  if (isBlankRichText(description)) return null;
    22	  const content = parseRichText(description);
    23	
    24	  return (
    25	    <chakra.div __css={styles} textStyle="body2" data-testid="product-description">
    26	      {content}
    27	    </chakra.div>
    28	  );
    29	};
